-- T-080: the two guarantees a dispute's money record has to carry in the database rather than in a
-- service, because a service can be bypassed by a migration, a psql session or the next person to
-- write a sweep.
--
-- 1. The decision log and the status log only grow (M3 D6). A dispute decision is exactly the kind
--    of record that gets challenged, audited, or cited in a later dispute between the same two
--    people; if it can be edited afterwards it is worth nothing. An appeal that overturns the
--    original writes a NEW row, it does not correct the old one. Generated by appendOnly() in
--    src/db/helpers/appendOnly.ts: UPDATE and DELETE raise KT001 for everyone including the owner,
--    and komtru_app holds INSERT and SELECT only.
--
-- 2. The two decision amounts sum to the escrowed total (M3 D4 and §5). The application checks this
--    first, in domain/decision.ts, and the ledger checks it again independently against the live
--    escrow balance — this is the middle of the three, and the only one that cannot be skipped by
--    a caller who reaches the table another way. A reviewer must not be able to record a decision
--    that loses or invents money.
CREATE OR REPLACE FUNCTION disputes.validate_decision_sums_to_escrow()
RETURNS trigger
LANGUAGE plpgsql
-- The function reads disputes.dispute_cases, which komtru_app can already select from; it is
-- deliberately NOT security definer, so it grants the caller no reach it did not have.
AS $$
DECLARE
  v_total bigint;
BEGIN
  SELECT total_escrow_minor INTO v_total
  FROM disputes.dispute_cases
  WHERE id = NEW.dispute_id;

  IF v_total IS NULL THEN
    RAISE EXCEPTION 'dispute % does not exist, so its decision cannot be checked', NEW.dispute_id
      USING ERRCODE = 'KT001';
  END IF;

  IF (NEW.amount_to_buyer_minor + NEW.amount_to_seller_minor) <> v_total THEN
    RAISE EXCEPTION
      'decision amounts (buyer %, seller %) do not sum to the escrowed total (%)',
      NEW.amount_to_buyer_minor, NEW.amount_to_seller_minor, v_total
      USING ERRCODE = 'KT001';
  END IF;

  RETURN NEW;
END;
$$;
--> statement-breakpoint
-- BEFORE INSERT only: there is no UPDATE path to guard, because the append-only trigger below
-- refuses every UPDATE on this table outright.
CREATE TRIGGER dispute_decision_log_validate_sum
  BEFORE INSERT ON "disputes"."dispute_decision_log"
  FOR EACH ROW EXECUTE FUNCTION disputes.validate_decision_sums_to_escrow();
--> statement-breakpoint
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "disputes"."dispute_decision_log" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "disputes"."dispute_decision_log" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "disputes"."dispute_decision_log" TO komtru_app;
--> statement-breakpoint
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "disputes"."dispute_status_changes" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "disputes"."dispute_status_changes" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "disputes"."dispute_status_changes" TO komtru_app;
